pub fn parse_n_from_args<I>(args: I) -> i32
where
    I: IntoIterator<Item = String>,
{
    let mut iter = args.into_iter();
    let _ = iter.next();
    iter.next().map_or(2, |value| atoi_i32(&value))
}

fn atoi_i32(input: &str) -> i32 {
    let bytes = input.as_bytes();
    let mut index = 0usize;

    while index < bytes.len() && bytes[index].is_ascii_whitespace() {
        index += 1;
    }

    let mut sign = 1i64;
    if index < bytes.len() {
        match bytes[index] {
            b'+' => index += 1,
            b'-' => {
                sign = -1;
                index += 1;
            }
            _ => {}
        }
    }

    let mut value = 0i64;
    let mut saw_digit = false;
    while index < bytes.len() && bytes[index].is_ascii_digit() {
        saw_digit = true;
        value = value
            .saturating_mul(10)
            .saturating_add(i64::from(bytes[index] - b'0'));
        index += 1;
    }

    if !saw_digit {
        return 0;
    }

    let signed = sign.saturating_mul(value);
    signed.clamp(i64::from(i32::MIN), i64::from(i32::MAX)) as i32
}

#[cfg(test)]
mod tests {
    use super::parse_n_from_args;

    #[test]
    fn uses_default_when_no_argument_is_present() {
        let args = vec!["test2".to_string()];
        assert_eq!(parse_n_from_args(args), 2);
    }

    #[test]
    fn matches_c_style_atoi_behavior() {
        let cases = [
            ("0", 0),
            ("1", 1),
            ("-2", -2),
            ("+2", 2),
            ("1.5", 1),
            ("foo", 0),
            ("", 0),
            (" 2", 2),
            (" ", 0),
        ];

        for (value, expected) in cases {
            let args = vec!["test2".to_string(), value.to_string()];
            assert_eq!(parse_n_from_args(args), expected);
        }
    }
}

pub type Point = [f64; 2];
pub type Ring = Vec<Point>;
pub type Polygon = Vec<Ring>;

pub fn build_polygon(n: i32) -> Polygon {
    let scale = f64::from(n);
    let mut polygon = vec![vec![[0.0, 0.0], [scale, 0.0], [scale, scale], [0.0, scale]]];

    if n > 1 {
        let quarter = 0.25 * scale;
        let three_quarters = 0.75 * scale;
        polygon.push(vec![
            [quarter, quarter],
            [three_quarters, quarter],
            [three_quarters, three_quarters],
            [quarter, three_quarters],
        ]);
    }

    polygon
}
